import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { createMarketEngine, type MarketEngine } from "./eventEngine";
import type { DashboardSnapshot } from "./types";

export interface AgentStreamValue {
  snapshot: DashboardSnapshot;
  paused: boolean;
  intervalMs: number;
  togglePause: () => void;
  advance: (count?: number) => void;
}

const AgentStreamContext = createContext<AgentStreamValue | null>(null);

export interface AgentStreamProviderProps {
  children: ReactNode;
  seed?: number;
  tickMs?: number;
  autoStart?: boolean;
  engine?: MarketEngine;
}

export function AgentStreamProvider({
  children,
  seed = 0x5eed1e,
  tickMs = 1800,
  autoStart = true,
  engine: injectedEngine,
}: AgentStreamProviderProps) {
  const engineRef = useRef<MarketEngine | null>(injectedEngine ?? null);
  if (!engineRef.current) {
    engineRef.current = createMarketEngine({ seed, tickMs });
  }
  const engine = engineRef.current;
  const [snapshot, setSnapshot] = useState<DashboardSnapshot>(() => engine.latest);
  const [paused, setPaused] = useState(!autoStart);

  const advance = useCallback(
    (count = 1) => {
      let next = engine.latest;
      const steps = Math.max(1, Math.floor(count));
      for (let i = 0; i < steps; i += 1) next = engine.tick();
      setSnapshot(next);
    },
    [engine],
  );

  useEffect(() => {
    if (paused) return;
    const handle = window.setInterval(() => {
      setSnapshot(engine.tick());
    }, tickMs);
    return () => window.clearInterval(handle);
  }, [engine, paused, tickMs]);

  const togglePause = useCallback(() => {
    setPaused((value) => !value);
  }, []);

  const value = useMemo<AgentStreamValue>(
    () => ({ snapshot, paused, intervalMs: tickMs, togglePause, advance }),
    [snapshot, paused, tickMs, togglePause, advance],
  );

  return <AgentStreamContext.Provider value={value}>{children}</AgentStreamContext.Provider>;
}

export function useAgentStream(): AgentStreamValue {
  const context = useContext(AgentStreamContext);
  if (!context) {
    throw new Error("useAgentStream must be used inside AgentStreamProvider");
  }
  return context;
}

export function useUtcClock(intervalMs = 1000): Date {
  const [now, setNow] = useState<Date>(() => new Date());
  useEffect(() => {
    const handle = window.setInterval(() => setNow(new Date()), intervalMs);
    return () => window.clearInterval(handle);
  }, [intervalMs]);
  return now;
}
