import { useId } from "react";
import type { AgentCardData, Tone } from "../data/types";
import { AgentGlyph } from "./AgentGrid";

function Sparkline({ data, tone }: { data: number[]; tone: Tone }) {
  const rawId = useId();
  const gradientId = `spark-${rawId.replace(/[^a-zA-Z0-9]/g, "")}`;
  const points = data.length > 1 ? data : [0, 0];
  const min = Math.min(...points);
  const max = Math.max(...points);
  const span = max - min || 1;
  const step = 100 / (points.length - 1);
  const coords = points.map((value, index) => {
    const x = index * step;
    const y = 26 - ((value - min) / span) * 22 - 2;
    return [x, y] as const;
  });
  const line = coords.map(([x, y], index) => `${index === 0 ? "M" : "L"}${x.toFixed(2)},${y.toFixed(2)}`).join(" ");
  const area = `${line} L100,30 L0,30 Z`;

  return (
    <svg
      className={`spark spark--${tone}`}
      viewBox="0 0 100 30"
      preserveAspectRatio="none"
      role="img"
      aria-label={`${tone} trend sparkline`}
    >
      <defs>
        <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="currentColor" stopOpacity="0.34" />
          <stop offset="100%" stopColor="currentColor" stopOpacity="0" />
        </linearGradient>
      </defs>
      <path d={area} fill={`url(#${gradientId})`} />
      <path d={line} fill="none" stroke="currentColor" strokeWidth="1.6" vectorEffect="non-scaling-stroke" />
      {coords.length > 0 ? (
        <circle cx={coords[coords.length - 1][0]} cy={coords[coords.length - 1][1]} r="1.8" fill="currentColor" />
      ) : null}
    </svg>
  );
}

function RefreshGlyph() {
  return (
    <svg viewBox="0 0 16 16" aria-hidden="true" className="refresh-glyph">
      <path
        d="M13 8a5 5 0 1 1-1.5-3.6M13 2v4H9"
